commit 90fef7300c75ca6b8834da0dcb710e27d599324e
Author: James Bonfield <jkb@sanger.ac.uk>
Date:   Mon Jan 25 09:32:50 2021 +0000

    More OSS-Fuzz detected fixes

    Credit to OSS-Fuzz

    - Clean up properly when XPACK output values are out of the accepted
      range.

      Fixes oss-fuzz 29827

    - Add "cp_end" arg to varint_get* funcs in cram_varint_decode_init so
      reading beyond the buffer can be spotted.

      Fixes oss-fuzz 29837

    - Set b->uncomp_size for FQZ decoder.  Already done in other codecs,
      just accidentally missed here.  Without it, it invalidates the
      boundary check in int32_get_blk.

      Fixes oss-fuzz 29855
      Fixes oss-fuzz 29908

    - Fixed memory leak in XDELTA when recovering from malformed data stream.

      Fixes oss-fuzz 29858
---
 cram/cram_codecs.c | 13 +++++++------
 cram/cram_io.c     |  1 +
 2 files changed, 8 insertions(+), 6 deletions(-)

diff --git a/cram/cram_codecs.c b/cram/cram_codecs.c
index 067319fc..63c6ea73 100644
--- a/cram/cram_codecs.c
+++ b/cram/cram_codecs.c
@@ -745,7 +745,7 @@ cram_codec *cram_varint_decode_init(cram_block_compression_hdr *hdr,
                                     enum cram_external_type option,
                                     int version, varint_vec *vv) {
     cram_codec *c;
-    char *cp = data;
+    char *cp = data, *cp_end = data+size;

     if (!(c = malloc(sizeof(*c))))
         return NULL;
@@ -775,8 +775,8 @@ cram_codec *cram_varint_decode_init(cram_block_compression_hdr *hdr,
     c->size   = cram_varint_decode_size;
     c->get_block = cram_varint_get_block;

-    c->u.varint.content_id = vv->varint_get32 (&cp, NULL, NULL);
-    c->u.varint.offset     = vv->varint_get64s(&cp, NULL, NULL);
+    c->u.varint.content_id = vv->varint_get32 (&cp, cp_end, NULL);
+    c->u.varint.offset     = vv->varint_get64s(&cp, cp_end, NULL);

     if (cp - data != size) {
         fprintf(stderr, "Malformed varint header stream\n");
@@ -1414,7 +1414,8 @@ cram_codec *cram_xpack_decode_init(cram_block_compression_hdr *hdr,
     int i;
     for (i = 0; i < c->u.xpack.nval; i++) {
         uint32_t v = vv->varint_get32(&cp, endp, NULL);
-        if (v >= 256) return NULL;
+        if (v >= 256)
+            goto malformed;
         c->u.xpack.rmap[i] = v; // reverse map: e.g 0-3 to P,A,C,K
     }

@@ -1714,7 +1715,7 @@ cram_codec *cram_xdelta_decode_init(cram_block_compression_hdr *hdr,
     char *cp = data;
     char *endp = data+size;

-    if (!(c = malloc(sizeof(*c))))
+    if (!(c = calloc(1, sizeof(*c))))
         return NULL;

     c->codec  = E_XDELTA;
@@ -1749,7 +1750,7 @@ cram_codec *cram_xdelta_decode_init(cram_block_compression_hdr *hdr,
     if (cp - data != size) {
     malformed:
         fprintf(stderr, "Malformed xdelta header stream\n");
-        free(c);
+        cram_xdelta_decode_free(c);
         return NULL;
     }

diff --git a/cram/cram_io.c b/cram/cram_io.c
index 30f109d6..8d257acc 100644
--- a/cram/cram_io.c
+++ b/cram/cram_io.c
@@ -1674,6 +1674,7 @@ int cram_uncompress_block(cram_block *b) {
         b->data = (unsigned char *)uncomp;
         b->alloc = uncomp_size;
         b->method = RAW;
+        b->uncomp_size = uncomp_size;
         break;
     }


commit 8510a0d2a5ac878f1a4b9a6683580bcdfa9196d3
Author: James Bonfield <jkb@sanger.ac.uk>
Date:   Thu Jan 28 17:06:25 2021 +0000

    Fix more OSS fuzz reported issues.

    Credit to OSS-Fuzz

    - Add bounds check in cram_const_decode_init.

      I've checked and this is the only use of the varint decoders that
      didn't have a bounds check.  Suitably sniffed out by the fuzzer.
      Good fuzzer!

      Fixes oss-fuzz 30012

    - Free the sub-encoding when initialising XRLE encoding fails due to
      malformed streams.  This removes a tiny memory leak.

      Fixes oss-fuzz 30014
---
 cram/cram_codecs.c | 6 +++---
 1 file changed, 3 insertions(+), 3 deletions(-)

diff --git a/cram/cram_codecs.c b/cram/cram_codecs.c
index e581ba3c..ab46fc29 100644
--- a/cram/cram_codecs.c
+++ b/cram/cram_codecs.c
@@ -964,7 +964,7 @@ cram_codec *cram_const_decode_init(cram_block_compression_hdr *hdr,
     c->size   = cram_const_decode_size;
     c->get_block = NULL;

-    c->u.xconst.val = vv->varint_get64s(&cp, NULL, NULL);
+    c->u.xconst.val = vv->varint_get64s(&cp, data+size, NULL);

     if (cp - data != size) {
         fprintf(stderr, "Malformed const header stream\n");
@@ -2118,7 +2118,7 @@ cram_codec *cram_xrle_decode_init(cram_block_compression_hdr *hdr,
     char *endp = data+size;
     int err = 0;

-    if (!(c = malloc(sizeof(*c))))
+    if (!(c = calloc(1, sizeof(*c))))
         return NULL;

     c->codec  = E_XRLE;
@@ -2175,7 +2175,7 @@ cram_codec *cram_xrle_decode_init(cram_block_compression_hdr *hdr,

  malformed:
     fprintf(stderr, "Malformed xrle header stream\n");
-    free(c);
+    cram_xrle_decode_free(c);
     return NULL;
 }


commit 79d8c948e6aaec343e6f07d9bab9f7edcf1fa368
Author: James Bonfield <jkb@sanger.ac.uk>
Date:   Thu Jan 21 16:42:34 2021 +0000

    Fix some fuzz issues in CRAM 3.1.

    Credit to OSS-Fuzz

    - Check for return value from RANS4x16 and ARITH codecs so a valid
      stream that is the wrong size still frees up the memory.
      Fixes oss-fuzz 29786
      Fixes oss-fuzz 29787
      Fixes oss-fuzz 29796

    - Check for return value from TOK3 codec so error is bubbled up
      Fixes oss-fuzz 29789
---
 cram/cram_io.c | 14 ++++++++++++--
 1 file changed, 12 insertions(+), 2 deletions(-)

diff --git a/cram/cram_io.c b/cram/cram_io.c
index 4f95f940..30f109d6 100644
--- a/cram/cram_io.c
+++ b/cram/cram_io.c
@@ -1680,8 +1680,12 @@ int cram_uncompress_block(cram_block *b) {
     case RANS_PR0: {
         unsigned int usize = b->uncomp_size, usize2;
         uncomp = (char *)rans_uncompress_4x16(b->data, b->comp_size, &usize2);
-        if (!uncomp || usize != usize2)
+        if (!uncomp)
+            return -1;
+        if (usize != usize2) {
+            free(uncomp);
             return -1;
+        }
         b->orig_method = RANS_PR0 + (b->data[0]&1)
             + 2*((b->data[0]&0x40)>0) + 4*((b->data[0]&0x80)>0);
         free(b->data);
@@ -1696,8 +1700,12 @@ int cram_uncompress_block(cram_block *b) {
     case ARITH_PR0: {
         unsigned int usize = b->uncomp_size, usize2;
         uncomp = (char *)arith_uncompress_to(b->data, b->comp_size, NULL, &usize2);
-        if (!uncomp || usize != usize2)
+        if (!uncomp)
             return -1;
+        if (usize != usize2) {
+            free(uncomp);
+            return -1;
+        }
         b->orig_method = ARITH_PR0 + (b->data[0]&1)
             + 2*((b->data[0]&0x40)>0) + 4*((b->data[0]&0x80)>0);
         free(b->data);
@@ -1712,6 +1720,8 @@ int cram_uncompress_block(cram_block *b) {
     case TOK3: {
         uint32_t out_len;
         uint8_t *cp = decode_names(b->data, b->comp_size, &out_len);
+        if (!cp)
+            return -1;
         b->orig_method = TOK3;
         b->method = RAW;
         free(b->data);
